    @push('scripts')<script>async function markPayrollPaid(event){event.preventDefault();if(!confirm('Tandai honor tutor ini sudah dicairkan?'))return false;const form=event.target;const response=await fetch(form.querySelector('input[type=hidden]').value,{method:'POST',headers:{'Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content}});const json=await response.json();if(!response.ok){alert(json.message||'Pencatatan gagal.');return false;}location.reload();return false;}</script>@endpush
